/// <mls fileReference="_102047_/l2/tarefas/web/contracts/inicio_gestor.defs.ts" enhancement="_blank"/>

/** Indicadores da equipe já calculados no servidor. */
export interface TotaisEquipe {
  readonly abertas: number;
  readonly vencemHoje: number;
  readonly atrasadas: number;
  readonly itensChecklistFeitos: number;
  readonly itensChecklistTotal: number;
  readonly progressoChecklist: string;
}

export interface ListaAbertasDetails {
  details: {
    readonly quantidadeTarefasAbertas: number;
  };
}

/** Lista com a quantidade de tarefas abertas. */
export interface ListaAbertas {
  id: string;
  nome: string;
  details: ListaAbertasDetails;
}

export interface TarefaAcaoDetails {
  details: {
    readonly aberta: boolean;
    readonly venceHoje: boolean;
    readonly atrasada: boolean;
    readonly progressoChecklist: string;
  };
}

export interface ListaRef {
  nome: string;
}

export interface MembroRefIdentification {
  details: {
    identification: {
      name: string;
    };
  };
}

export interface MembroRefDetails {
  identification: MembroRefIdentification;
}

export interface MembroRef {
  details: MembroRefDetails;
}

/** Tarefa aberta atrasada ou vencendo hoje, com lista e responsável. */
export interface TarefaAcao {
  id: string;
  titulo: string;
  status: 'aFazer' | 'emAndamento' | 'emRevisao' | 'concluida' | 'cancelada';
  prioridade: 'low' | 'medium' | 'high';
  prazo: string;
  listaId: string;
  responsavelId: string;
  details: TarefaAcaoDetails;
  lista: ListaRef;
  membroEquipe: MembroRef;
}

export interface Inicio_gestorContracts {
  /**
   * Finalidade: Carrega, ao abrir o início do gestor, o panorama da equipe: totais de tarefas abertas, vencendo hoje e atrasadas, progresso das checklists e tarefas abertas por lista.
   * Entrada: Nenhuma entrada; o escopo é toda a equipe (organização) do gestor da sessão.
   * Processamento: Conta as tarefas da organização com details.aberta (status aFazer, emAndamento ou emRevisao), as que vencem hoje (aberta e prazo = hoje) e as atrasadas (aberta e prazo < hoje); esses indicadores derivados são calculados na consulta, nunca gravados. Soma os itens de checklist (ItemChecklist.feito por tarefaId) das tarefas abertas para obter feitos/total e o texto do progresso. Lista as listas ativas ordenadas por nome com quantidadeTarefasAbertas calculada pela contagem de tarefas abertas por listaId.
   * Saída: totais com os números já prontos para os blocos de destaque e listas com nome e quantidade de tarefas abertas, para o gestor saber onde olhar primeiro.
   */
  'tarefas.inicio_gestor.qryPanoramaEquipe': {
    kind: 'qry';
    input: {};
    output: { totais: TotaisEquipe; listas: ListaAbertas[] };
    rules: [];
    access: { actors: ['gestor']; grants: ['gestorTarefasEquipe', 'gestorListas', 'gestorMembros']; scope: 'organization' };
  };
  /**
   * Finalidade: Traz a caixa de tarefas da equipe que podem pedir ação do gestor: abertas e atrasadas ou vencendo hoje.
   * Entrada: page: página pedida (começa em 1); pageSize: quantidade de tarefas por página.
   * Processamento: Filtra as tarefas da organização com status aFazer, emAndamento ou emRevisao cujo prazo é hoje ou anterior; calcula aberta, venceHoje, atrasada e progressoChecklist (itens feitos do total da checklist) na consulta, sem gravar. Ordena atrasadas primeiro, por prazo crescente e prioridade decrescente. Junta o nome da lista (Lista.nome por listaId) e o nome do responsável lido no cadastro mestre (MembroEquipe.details.identification.name por responsavelId), carregados em lote.
   * Saída: Página { items, page, pageSize, hasMore } de tarefas com título, lista, responsável, prioridade, prazo, situação e progresso da checklist, prontas para os cartões; a escolha leva a Tarefas da equipe.
   */
  'tarefas.inicio_gestor.qryTarefasPedemAcao': {
    kind: 'qry';
    input: { page: number; pageSize: number };
    output: { tarefas: { items: TarefaAcao[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['gestor']; grants: ['gestorTarefasEquipe', 'gestorListas', 'gestorMembros']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/tarefas/web/contracts/inicio_membro.defs.ts" enhancement="_blank"/>

/** Nome da lista à qual a tarefa pertence. */
export interface ListaNome {
  nome: string;
}

/** Campos calculados da tarefa usados no panorama. */
export interface TarefaResumoDetalhes {
  details: {
    readonly aberta: boolean;
    readonly venceHoje: boolean;
    readonly atrasada: boolean;
    readonly progressoChecklist: string;
  };
}

/** Tarefa aberta do membro no panorama, com a lista e o progresso da checklist. */
export interface TarefaResumo {
  id: string;
  titulo: string;
  status: 'aFazer' | 'emAndamento' | 'emRevisao' | 'concluida' | 'cancelada';
  prazo: string;
  prioridade: 'low' | 'medium' | 'high';
  listaId: string;
  lista: ListaNome;
  details: TarefaResumoDetalhes;
}

/** Indicadores já calculados das tarefas abertas do membro e a lista dessas tarefas. */
export interface ResumoMinhasTarefas {
  readonly quantidadeAbertas: number;
  readonly quantidadeVencemHoje: number;
  readonly quantidadeAtrasadas: number;
  tarefas: TarefaResumo[];
}

/** Tarefa incluída no aviso diário, com o prazo e a situação do prazo no momento do aviso. */
export interface AvisoTarefa {
  details: {
    tarefas: {
      tarefaId: string;
      prazo: string;
      situacaoPrazo: 'dueToday' | 'overdue';
    };
  };
}

/** Detalhes do aviso diário: geração, contagens e tarefas. */
export interface AvisoDetalhes {
  details: {
    readonly geradoEm: string;
    readonly quantidadeTarefas: number;
    readonly quantidadeAtrasadas: number;
  };
  tarefas: AvisoTarefa[];
}

/** Aviso diário de vencimentos de hoje do membro. */
export interface AvisoDoDia {
  id: string;
  readonly dataReferencia: string;
  status: 'pending' | 'completed' | 'failed';
  details: AvisoDetalhes;
}

/** Identificação do membro: apenas o nome. */
export interface MembroNomeIdentificacao {
  details: {
    identification: {
      name: string;
    };
  };
}

/** Detalhes do membro reduzidos à identificação. */
export interface MembroNomeDetalhes {
  identification: MembroNomeIdentificacao;
}

/** Membro da equipe com o nome a exibir. */
export interface MembroNome {
  details: MembroNomeDetalhes;
}

/** Detalhes da tarefa pendente: progresso da checklist e dados da última devolução. */
export interface PendenciaDetalhes {
  details: {
    readonly progressoChecklist: string;
    motivoDevolucao?: string;
    devolvidaEm?: string;
  };
}

/** Tarefa que espera uma ação do membro, com a ação esperada, os nomes do responsável e do criador e a versão para os comandos. */
export interface Pendencia {
  id: string;
  version: number;
  titulo: string;
  status: 'aFazer' | 'emAndamento' | 'emRevisao' | 'concluida' | 'cancelada';
  prazo: string;
  prioridade: 'low' | 'medium' | 'high';
  responsavelId: string;
  criadorId: string;
  responsavel: MembroNome;
  criador: MembroNome;
  readonly acaoEsperada: string;
  details: PendenciaDetalhes;
}

export interface Inicio_membroContracts {
  /**
   * Finalidade: Carrega de uma vez tudo o que a tela inicial do membro mostra ao abrir: o panorama das suas tarefas abertas, o aviso diário de hoje e a caixa do que espera por uma ação dele.
   * Entrada: Sem parâmetros: o membro é resolvido pela sessão e a data de hoje pelo servidor.
   * Processamento: Resumo: filtra as tarefas cujo responsável é o membro da sessão e que estão abertas (details.aberta, calculado: aFazer, emAndamento ou emRevisao); conta no servidor o total de abertas, as que vencem hoje (details.venceHoje) e as atrasadas (details.atrasada); lista essas tarefas ordenadas por prazo, com o nome da lista e o progresso da checklist (details.progressoChecklist, calculado pela contagem de itens feitos sobre o total). Campos derivados são calculados, nunca gravados. Aviso: lê o aviso do membro com dataReferencia igual a hoje; pela regra avisoUnicoPorResponsavelEDia há no máximo um; ele traz apenas tarefas abertas que vencem hoje ou estão atrasadas (avisoSomenteTarefasAbertasVencendo); se o processo das 8h ainda não gerou, volta vazio. Pendências: junta as tarefas em que o membro é responsável e está em aFazer (acaoEsperada ’iniciar’) ou emAndamento (acaoEsperada ’enviarParaRevisao’, ou ’ajustar’ quando há devolvidaEm), conforme somenteResponsavelExecuta, e as tarefas que ele criou em emRevisao (acaoEsperada ’revisar’), conforme somenteCriadorRevisa; inclui motivo e data da devolução, nomes do responsável e do criador lidos do cadastro mestre, e a versão para os comandos; ordena por prazo e prioridade.
   * Saída: resumo com os três indicadores já calculados e as tarefas abertas; avisoHoje com data, situação, contagens e tarefas do aviso (opcional); pendencias com cada tarefa e a ação esperada, para a página exibir a ação certa em cada item.
   */
  'tarefas.inicio_membro.qryInicioMembro': {
    kind: 'qry';
    input: {};
    output: { resumo: ResumoMinhasTarefas; avisoHoje?: AvisoDoDia; pendencias: Pendencia[] };
    rules: ['avisoUnicoPorResponsavelEDia', 'avisoSomenteTarefasAbertasVencendo', 'somenteResponsavelExecuta', 'somenteCriadorRevisa'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroAvisosProprios', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Inicia uma tarefa atribuída ao membro, passando-a de a fazer para em andamento.
   * Entrada: tarefaId: tarefa a iniciar; version: versão lida, para controle de concorrência.
   * Processamento: Aplica a transição iniciar (aFazer → emAndamento). Recusa se o membro da sessão não for o responsável (somenteResponsavelExecuta) e se a tarefa estiver concluída ou cancelada (tarefaEncerradaNaoTransiciona); recusa se a versão estiver desatualizada. A sala de discussão recebe a mensagem da mudança. Depois recompõe o resumo e as pendências como em qryInicioMembro.
   * Saída: resumo e pendencias atualizados, para a página redesenhar o panorama e a caixa sem nova chamada (a tarefa passa a esperar o envio para revisão).
   */
  'tarefas.inicio_membro.cmdIniciarTarefa': {
    kind: 'cmd';
    writes: 'Tarefa.iniciar';
    input: { id: string; version: number };
    output: { resumo: ResumoMinhasTarefas; pendencias: Pendencia[] };
    rules: ['somenteResponsavelExecuta', 'tarefaEncerradaNaoTransiciona'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroAvisosProprios', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Envia para revisão do criador uma tarefa em andamento do membro, inclusive uma tarefa devolvida já ajustada.
   * Entrada: tarefaId: tarefa a enviar; version: versão lida, para controle de concorrência.
   * Processamento: Aplica a transição enviarParaRevisao (emAndamento → emRevisao). Recusa se o membro da sessão não for o responsável (somenteResponsavelExecuta) ou se a tarefa estiver encerrada (tarefaEncerradaNaoTransiciona); recusa versão desatualizada. O criador passa a ser quem age agora e é avisado. Recompõe resumo e pendências.
   * Saída: resumo e pendencias atualizados; a tarefa sai da caixa do membro, salvo se ele também for o criador, quando aparece para revisar.
   */
  'tarefas.inicio_membro.cmdEnviarParaRevisao': {
    kind: 'cmd';
    writes: 'Tarefa.enviarParaRevisao';
    input: { id: string; version: number };
    output: { resumo: ResumoMinhasTarefas; pendencias: Pendencia[] };
    rules: ['somenteResponsavelExecuta', 'tarefaEncerradaNaoTransiciona'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroAvisosProprios', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Aceita a entrega de uma tarefa criada pelo membro e que está em revisão, concluindo-a.
   * Entrada: tarefaId: tarefa a aceitar; version: versão lida, para controle de concorrência.
   * Processamento: Aplica a transição aceitar (emRevisao → concluida), registrando concluidaEm. Recusa se o membro da sessão não for o criador (somenteCriadorRevisa) ou se a tarefa já estiver encerrada (tarefaEncerradaNaoTransiciona); recusa versão desatualizada. A sala recebe a mensagem. Recompõe resumo e pendências.
   * Saída: resumo e pendencias atualizados; a tarefa concluída sai da caixa e das abertas.
   */
  'tarefas.inicio_membro.cmdAceitarEntrega': {
    kind: 'cmd';
    writes: 'Tarefa.aceitar';
    input: { id: string; version: number };
    output: { resumo: ResumoMinhasTarefas; pendencias: Pendencia[] };
    rules: ['somenteCriadorRevisa', 'tarefaEncerradaNaoTransiciona'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroAvisosProprios', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Devolve para ajuste, com o motivo, uma tarefa criada pelo membro que está em revisão.
   * Entrada: tarefaId: tarefa a devolver; version: versão lida; motivoDevolucao: texto do motivo, obrigatório.
   * Processamento: Aplica a transição devolver (emRevisao → emAndamento). Recusa se o membro da sessão não for o criador (somenteCriadorRevisa), se o motivo estiver vazio (devolucaoExigeMotivo) ou se a tarefa estiver encerrada (tarefaEncerradaNaoTransiciona); recusa versão desatualizada. Grava o motivo e devolvidaEm na tarefa; o responsável volta a ser quem age agora e é avisado. Recompõe resumo e pendências.
   * Saída: resumo e pendencias atualizados; a tarefa sai da revisão do membro, salvo se ele também for o responsável, quando aparece para ajustar.
   */
  'tarefas.inicio_membro.cmdDevolverComMotivo': {
    kind: 'cmd';
    writes: 'Tarefa.devolver';
    input: { id: string; version: number; details: { motivoDevolucao: string } };
    output: { resumo: ResumoMinhasTarefas; pendencias: Pendencia[] };
    rules: ['somenteCriadorRevisa', 'devolucaoExigeMotivo', 'tarefaEncerradaNaoTransiciona'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroAvisosProprios', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
}

/// <mls fileReference="_102047_/l2/tarefas/web/contracts/listas.defs.ts" enhancement="_blank"/>

/** Detalhes da lista exibidos no cadastro: tipo e tarefas abertas. */
export interface ListaResumoDetalhes {
  details: {
    tipo: 'project' | 'area';
  };
  readonly quantidadeTarefasAbertas: number;
}

/** Linha do cadastro de listas. */
export interface ListaResumo {
  id: string;
  nome: string;
  ativa: boolean;
  details: ListaResumoDetalhes;
}

/** Detalhes editáveis da lista. */
export interface ListaEdicaoDetalhes {
  details: {
    tipo: 'project' | 'area';
    descricao?: string;
  };
}

/** Registro da lista carregado no formulário de edição. */
export interface ListaEdicao {
  id: string;
  version: number;
  nome: string;
  ativa: boolean;
  details: ListaEdicaoDetalhes;
}

export interface ListasContracts {
  /**
   * Finalidade: Carrega, ao abrir a página, todas as listas da organização para o gestor escolher qual manter.
   * Entrada: Nenhuma entrada; o escopo é a organização do gestor da sessão.
   * Processamento: Busca todas as listas (ativas e inativas) ordenadas por nome. Para cada lista calcula quantidadeTarefasAbertas contando as tarefas com listaId igual à lista e situação aFazer, emAndamento ou emRevisao; é um campo derivado, calculado na consulta e nunca gravado. Lista não paginada, pois o número de listas de projetos e áreas cabe numa tela.
   * Saída: Lista de ListaResumo com id, nome, ativa, tipo e quantidade de tarefas abertas, no formato que o cadastro exibe.
   */
  'tarefas.listas.listarListas': {
    kind: 'qry';
    input: {};
    output: { listas: ListaResumo[] };
    rules: [];
    access: { actors: ['gestor']; grants: ['gestorTarefasEquipe', 'gestorListas']; scope: 'organization' };
  };
  /**
   * Finalidade: Abre os dados de uma lista escolhida no cadastro para edição no formulário.
   * Entrada: listaId: id da lista selecionada no cadastro.
   * Processamento: Lê a lista pelo id (read.byId) dentro da organização do gestor.
   * Saída: ListaEdicao com id, version, nome, ativa, tipo e descrição, para preencher o formulário e enviar a versão ao salvar.
   */
  'tarefas.listas.obterLista': {
    kind: 'qry';
    input: { listaId: string };
    output: { lista: ListaEdicao };
    rules: [];
    access: { actors: ['gestor']; grants: ['gestorTarefasEquipe', 'gestorListas']; scope: 'organization' };
  };
  /**
   * Finalidade: Cadastra uma nova lista de projeto ou área.
   * Entrada: nome: nome da lista; ativa: se recebe novas tarefas; tipo: project ou area; descricao: texto livre opcional.
   * Processamento: listaMantidaPorGestor: recusa se o usuário da sessão não for gestor. listaNomeUnico: recusa se já existir lista com o mesmo nome. Grava a lista; id e version são gerados pelo sistema; quantidadeTarefasAbertas é calculada (zero para lista nova), nunca gravada.
   * Saída: lista: a linha ListaResumo para inserir no cadastro; registro: ListaEdicao com id e version para o formulário continuar em edição sem nova chamada.
   */
  'tarefas.listas.criarLista': {
    kind: 'cmd';
    writes: 'Lista.create';
    input: { nome: string; ativa: boolean; details: { tipo: 'project' | 'area'; descricao?: string } };
    output: { lista: ListaResumo; registro: ListaEdicao };
    rules: ['listaMantidaPorGestor', 'listaNomeUnico'];
    access: { actors: ['gestor']; grants: ['gestorTarefasEquipe', 'gestorListas']; scope: 'organization' };
  };
  /**
   * Finalidade: Altera nome, tipo, descrição e situação ativa de uma lista existente.
   * Entrada: id e version: lista editada e versão lida (controle de concorrência); nome, ativa, tipo, descricao: novos valores.
   * Processamento: listaMantidaPorGestor: recusa se o usuário não for gestor. listaNomeUnico: recusa se outra lista já tiver o mesmo nome. Recusa se a version não for a atual. Ao inativar, a lista deixa de aparecer na escolha ao criar tarefas. quantidadeTarefasAbertas é recalculada na resposta, nunca gravada.
   * Saída: lista: a linha ListaResumo atualizada para substituir no cadastro; registro: ListaEdicao com a nova version para o formulário.
   */
  'tarefas.listas.salvarLista': {
    kind: 'cmd';
    writes: 'Lista.update';
    input: { id: string; version: number; nome: string; ativa: boolean; details: { tipo: 'project' | 'area'; descricao?: string } };
    output: { lista: ListaResumo; registro: ListaEdicao };
    rules: ['listaMantidaPorGestor', 'listaNomeUnico'];
    access: { actors: ['gestor']; grants: ['gestorTarefasEquipe', 'gestorListas']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/tarefas/web/contracts/membros_equipe.defs.ts" enhancement="_blank"/>

/** Pessoa da equipe como aparece na lista e no cadastro: identificação, situação, país, papéis e contatos. */
export interface MembroEquipeResumo {
  id: string;
  version: number;
  details: MembroEquipeDetalhes;
}

export interface MembroEquipeDetalhes {
  identification: MembroEquipeIdentificacao;
  base: MembroEquipeBase;
}

export interface MembroEquipeIdentificacao {
  details: {
    identification: {
      name: string;
      readonly status: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
      countryCode: string;
      readonly tags: string;
    };
  };
}

export interface MembroEquipeBase {
  details: {
    base: {
      readonly contacts: string;
    };
  };
}

export interface Membros_equipeContracts {
  /**
   * Finalidade: Carrega, ao abrir a página, as pessoas da equipe (papel tarefas.MembroEquipe) para o gestor ver quem pode criar e receber tarefas e escolher quem atualizar.
   * Entrada: page e pageSize: página da lista; busca: trecho opcional do nome para filtrar as pessoas.
   * Processamento: Lista os membros da organização que têm o papel tarefas.MembroEquipe em details.identification.tags, filtrando pelo nome quando houver busca, ordenados por nome. Situação, papéis e resumo de contatos são campos derivados lidos do cadastro mestre, nunca calculados ou gravados aqui. Não devolve o consentimento de privacidade (campo negado ao gestor).
   * Saída: Página { items, page, pageSize, hasMore } com id, version, nome, situação, país, papéis e contatos de cada pessoa, no formato que a lista mostra.
   */
  'tarefas.membros_equipe.listarMembrosEquipe': {
    kind: 'qry';
    input: { busca?: string; page: number; pageSize: number };
    output: { membros: { items: MembroEquipeResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['gestor']; grants: ['gestorMembros']; scope: 'organization' };
  };
  /**
   * Finalidade: Carrega a pessoa escolhida na lista para abrir seus dados no formulário de cadastro.
   * Entrada: id: identificador (mdmId) da pessoa selecionada.
   * Processamento: Lê o membro pelo id (read.byId) com a versão atual, para que a edição use o controle de concorrência otimista.
   * Saída: A pessoa com id, version, nome, país e situação, que o formulário preenche.
   */
  'tarefas.membros_equipe.obterMembroEquipe': {
    kind: 'qry';
    input: { id: string };
    output: { membro: MembroEquipeResumo };
    rules: [];
    access: { actors: ['gestor']; grants: ['gestorMembros']; scope: 'organization' };
  };
  /**
   * Finalidade: Cadastra uma nova pessoa na equipe para que ela possa criar e receber tarefas.
   * Entrada: name: nome como aparece nas tarefas; countryCode: país que define as regras de privacidade.
   * Processamento: Cria ou anexa a pessoa no cadastro mestre (register.createOrAttach) com o papel tarefas.MembroEquipe, sem duplicar quem já existe. Id, versão, subtipo, situação, papéis e contatos são definidos pela plataforma, não pelo endpoint.
   * Saída: A pessoa criada com id, version e dados derivados, para inserir na lista e manter no formulário sem nova chamada.
   */
  'tarefas.membros_equipe.cadastrarPessoa': {
    kind: 'cmd';
    writes: 'MembroEquipe.create';
    input: { details: { identification: { name: string; countryCode: string } } };
    output: { membro: MembroEquipeResumo };
    rules: [];
    access: { actors: ['gestor']; grants: ['gestorMembros']; scope: 'organization' };
  };
  /**
   * Finalidade: Corrige o nome e o país da pessoa selecionada, mantendo correto como ela aparece nas tarefas.
   * Entrada: id e version: pessoa editada e versão lida; name: novo nome; countryCode: novo país.
   * Processamento: Atualiza nome e país no cadastro mestre (edit.platformFields), recusando a gravação se a versão não for a atual (concorrência otimista). Campos derivados não são alterados.
   * Saída: A pessoa atualizada com a nova versão, para atualizar a linha da lista e o formulário sem nova chamada.
   */
  'tarefas.membros_equipe.salvarAlteracoesPessoa': {
    kind: 'cmd';
    writes: 'MembroEquipe.update';
    input: { id: string; version: number; details: { identification: { name: string; countryCode: string } } };
    output: { membro: MembroEquipeResumo };
    rules: [];
    access: { actors: ['gestor']; grants: ['gestorMembros']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/tarefas/web/contracts/meus_avisos.defs.ts" enhancement="_blank"/>

/** Totais e datas de envio de um aviso, para a lista e o histórico. */
export interface AvisoResumoDetalhes {
  details: {
    readonly quantidadeTarefas: number;
    readonly quantidadeAtrasadas: number;
    readonly geradoEm: string;
    readonly finalizadoEm?: string;
    motivoFalha?: string;
  };
}

/** Um aviso diário na lista e no histórico de envio. */
export interface AvisoResumo {
  id: string;
  readonly dataReferencia: string;
  status: 'pending' | 'completed' | 'failed';
  details: AvisoResumoDetalhes;
}

/** Dados atuais da tarefa incluída no aviso. */
export interface TarefaResumo {
  id: string;
  titulo: string;
  status: 'aFazer' | 'emAndamento' | 'emRevisao' | 'concluida' | 'cancelada';
  prazo: string;
}

/** Linha do aviso: tarefa com o prazo e a situação do prazo no dia do aviso. */
export interface TarefaAviso {
  details: {
    tarefas: {
      tarefaId: string;
      prazo: string;
      situacaoPrazo: 'dueToday' | 'overdue';
    };
  };
  tarefa: TarefaResumo;
}

/** Totais e linhas do aviso aberto. */
export interface AvisoDetalheDetalhes {
  details: {
    readonly quantidadeTarefas: number;
    readonly quantidadeAtrasadas: number;
  };
  tarefas: TarefaAviso[];
}

/** Aviso aberto com suas tarefas que vencem hoje ou estão atrasadas. */
export interface AvisoDetalhe {
  id: string;
  readonly dataReferencia: string;
  status: 'pending' | 'completed' | 'failed';
  details: AvisoDetalheDetalhes;
}

export interface Meus_avisosContracts {
  /**
   * Finalidade: Abre a página Meus avisos de uma vez: a lista paginada dos avisos diários do usuário da sessão, que também alimenta o histórico de envio, e o aviso mais recente (o de hoje) já aberto com as suas tarefas.
   * Entrada: responsavelId: membro da sessão (vem do contexto, nunca da tela); page e pageSize: página da lista de avisos.
   * Processamento: Filtra AvisoVencimento pelo responsável da sessão (escopo own) e ordena por dataReferencia decrescente, com o aviso de hoje primeiro; pela regra avisoUnicoPorResponsavelEDia há no máximo um aviso por data, sem agrupamento. Para cada aviso devolve status, geradoEm, finalizadoEm, motivoFalha e os totais quantidadeTarefas e quantidadeAtrasadas, que são calculados pelo servidor a partir das linhas (contagem total e contagem com situacaoPrazo = overdue), nunca gravados pelo endpoint. Para o aviso mais recente compõe as linhas details.tarefas (tarefaId, prazo, situacaoPrazo) com título, situação e prazo atuais de cada Tarefa; as linhas são as que o processo gravou segundo avisoSomenteTarefasAbertasVencendo (tarefas abertas com prazo no dia ou vencido).
   * Saída: avisos: página { items, page, pageSize, hasMore } para a lista e o histórico; avisoAberto: o aviso de hoje (ou o mais recente) com totais e linhas, ausente se o usuário ainda não recebeu aviso.
   */
  'tarefas.meus_avisos.carregarMeusAvisos': {
    kind: 'qry';
    input: { responsavelId: string; page: number; pageSize: number };
    output: { avisos: { items: AvisoResumo[]; page: number; pageSize: number; hasMore: boolean }; avisoAberto?: AvisoDetalhe };
    rules: ['avisoUnicoPorResponsavelEDia', 'avisoSomenteTarefasAbertasVencendo'];
    access: { actors: ['gestor', 'membroEquipe']; grants: ['membroTarefasProprias', 'membroAvisosProprios', 'gestorTarefasEquipe', 'gestorAvisosProprios']; scope: 'own' };
  };
  /**
   * Finalidade: Carrega o aviso que o usuário escolheu na lista, com as tarefas que ele trouxe.
   * Entrada: avisoId: id do aviso selecionado na lista.
   * Processamento: Lê o AvisoVencimento por id e recusa se não pertencer ao responsável da sessão (escopo own). Compõe as linhas details.tarefas (tarefaId, prazo e situacaoPrazo do momento do aviso) com título, situação e prazo atuais de cada Tarefa. As linhas são as gravadas pelo processo diário conforme avisoSomenteTarefasAbertasVencendo. quantidadeTarefas e quantidadeAtrasadas são calculadas pelo servidor a partir das linhas.
   * Saída: aviso: o aviso com data, situação, totais e linhas, para substituir o aviso aberto no detalhe.
   */
  'tarefas.meus_avisos.abrirAviso': {
    kind: 'qry';
    input: { avisoId: string };
    output: { aviso: AvisoDetalhe };
    rules: ['avisoSomenteTarefasAbertasVencendo'];
    access: { actors: ['gestor', 'membroEquipe']; grants: ['membroTarefasProprias', 'membroAvisosProprios', 'gestorTarefasEquipe', 'gestorAvisosProprios']; scope: 'own' };
  };
}

/// <mls fileReference="_102047_/l2/tarefas/web/contracts/minhas_tarefas.defs.ts" enhancement="_blank"/>

/** Nome da lista da tarefa. */
export interface ListaNome {
  nome: string;
}

/** Identificação do membro lida no cadastro mestre. */
export interface MembroIdentificacao {
  details: {
    identification: {
      name: string;
      readonly status?: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
    };
  };
}

/** Detalhes do membro, aninhados como na ontologia. */
export interface MembroNomeDetalhes {
  identification: MembroIdentificacao;
}

/** Responsável ou criador exibido pelo nome. */
export interface MembroNome {
  details: MembroNomeDetalhes;
}

/** Membro ativo que pode ser escolhido como responsável. */
export interface MembroOpcao {
  responsavelId: string;
  details: MembroNomeDetalhes;
}

export interface ListaOpcaoDetalhes {
  details: {
    tipo: 'project' | 'area';
  };
}

/** Lista disponível para receber a tarefa no formulário. */
export interface ListaOpcao {
  tarefa: {
    listaId: string;
  };
  nome: string;
  ativa: boolean;
  details: ListaOpcaoDetalhes;
}

export interface TarefaResumoDetalhes {
  details: {
    readonly quantidadeSubtarefas: number;
    readonly progressoChecklist: string;
    readonly venceHoje: boolean;
    readonly atrasada: boolean;
    devolvidaEm?: string;
  };
}

/** Linha da lista de minhas tarefas, usada também para atualizar a linha após um comando. */
export interface TarefaResumo {
  id: string;
  version: number;
  titulo: string;
  listaId: string;
  lista: ListaNome;
  responsavelId: string;
  responsavel: MembroNome;
  criadorId: string;
  criador: MembroNome;
  prioridade: 'low' | 'medium' | 'high';
  prazo: string;
  status: 'aFazer' | 'emAndamento' | 'emRevisao' | 'concluida' | 'cancelada';
  details: TarefaResumoDetalhes;
}

export interface ItemChecklistLinhaDetalhes {
  details: {
    descricao: string;
    marcadoEm?: string;
  };
}

/** Item da checklist da tarefa aberta, na ordem. */
export interface ItemChecklistLinha {
  id: string;
  version: number;
  ordem: number;
  feito: boolean;
  details: ItemChecklistLinhaDetalhes;
}

export interface TarefaAbertaDetalhes {
  details: {
    descricao?: string;
    motivoDevolucao?: string;
    devolvidaEm?: string;
    concluidaEm?: string;
    canceladaEm?: string;
    readonly progressoChecklist: string;
  };
}

/** Tarefa aberta com nomes, checklist e marcos do histórico; serve ao detalhe, às ações, ao histórico e ao formulário de edição. */
export interface TarefaAberta {
  id: string;
  version: number;
  titulo: string;
  status: 'aFazer' | 'emAndamento' | 'emRevisao' | 'concluida' | 'cancelada';
  prioridade: 'low' | 'medium' | 'high';
  prazo: string;
  listaId: string;
  lista: ListaNome;
  criadorId: string;
  criador: MembroNome;
  responsavelId: string;
  responsavel: MembroNome;
  readonly criadaEm: string;
  details: TarefaAbertaDetalhes;
  checklist: ItemChecklistLinha[];
}

export interface ItemChecklistEntradaDetalhes {
  details: {
    descricao: string;
  };
}

/** Item da checklist enviado pelo formulário; sem id é um item novo. */
export interface ItemChecklistEntrada {
  id?: string;
  version?: number;
  ordem: number;
  details: ItemChecklistEntradaDetalhes;
}

export interface Minhas_tarefasContracts {
  /**
   * Finalidade: Carrega a página de tarefas que o membro da sessão criou ou pelas quais é responsável, já com nomes da lista, do responsável e do criador.
   * Entrada: criadasPorMim: só as tarefas com o membro da sessão como criador; atribuidasAMim: só as em que ele é responsável; status: filtra pela situação (ex.: emRevisao); somenteDevolvidas: só as que têm devolução registrada e seguem em andamento; page/pageSize: paginação.
   * Processamento: Resolve o membro da sessão pelo login e limita a visão às tarefas em que ele é criador ou responsável (editarSomenteTarefaVisivel). Aplica os filtros, ordena por prazo e lê no cadastro mestre os nomes de responsável e criador. venceHoje, atrasada, quantidadeSubtarefas e progressoChecklist são campos derivados calculados pelo servidor (prazo vs. data atual em tarefas abertas; contagem de subtarefas; itens feitos/total), nunca gravados.
   * Saída: tarefas paginadas { items, page, pageSize, hasMore } com o necessário para a lista destacar o que vence hoje ou está atrasado.
   */
  'tarefas.minhas_tarefas.minhasTarefas': {
    kind: 'qry';
    input: { criadasPorMim?: boolean; atribuidasAMim?: boolean; status?: 'aFazer' | 'emAndamento' | 'emRevisao' | 'concluida' | 'cancelada'; somenteDevolvidas?: boolean; page: number; pageSize: number };
    output: { tarefas: { items: TarefaResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['editarSomenteTarefaVisivel'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Abre a tarefa escolhida na lista com tudo o que o detalhe, as ações, o histórico e o formulário de edição mostram.
   * Entrada: tarefaId: id da tarefa selecionada na lista ou vinda do aviso.
   * Processamento: Recusa a tarefa se o membro da sessão não for criador nem responsável (editarSomenteTarefaVisivel). Lê a tarefa, o nome da lista, os nomes de criador e responsável no cadastro mestre e a checklist pela tarefaId ordenada por ordem. progressoChecklist é derivado (itens feitos do total), calculado pelo servidor.
   * Saída: tarefa com checklist e marcos (criadaEm, devolvidaEm com motivo, concluidaEm, canceladaEm) para o histórico, e version para os comandos.
   */
  'tarefas.minhas_tarefas.tarefaAberta': {
    kind: 'qry';
    input: { tarefaId: string };
    output: { tarefa: TarefaAberta };
    rules: ['editarSomenteTarefaVisivel'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Carrega as listas onde o membro pode criar ou mover uma tarefa.
   * Entrada: Nenhuma.
   * Processamento: Lista as listas da organização filtradas por ativa = true, ordenadas por nome; listas inativas não aparecem porque não recebem tarefas (listaInativaNaoRecebeTarefa).
   * Saída: listas com id, nome, ativa e tipo para o seletor do formulário.
   */
  'tarefas.minhas_tarefas.opcoesFormulario': {
    kind: 'qry';
    input: {};
    output: { listas: ListaOpcao[] };
    rules: ['listaInativaNaoRecebeTarefa'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Busca pelo nome os membros que podem ser escolhidos como responsável ao criar ou trocar o responsável.
   * Entrada: termo: trecho do nome digitado.
   * Processamento: Localiza membros por nome no cadastro mestre e devolve só os com situação Active (responsavelDeveSerMembroAtivo), limitado a poucos resultados.
   * Saída: membros com id, nome e situação para o seletor de responsável.
   */
  'tarefas.minhas_tarefas.buscarResponsaveis': {
    kind: 'qry';
    input: { termo: string };
    output: { membros: MembroOpcao[] };
    rules: ['responsavelDeveSerMembroAtivo'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Cria a tarefa com sua checklist inicial e a atribui ao responsável escolhido.
   * Entrada: chaveCriacao: chave gerada ao abrir o formulário; listaId, titulo, descricao, prioridade, prazo, responsavelId: campos da tarefa; criadorId: id do membro da sessão, que será o criador e revisor da tarefa; checklist: itens com ordem e descrição.
   * Processamento: Em uma transação grava a tarefa em aFazer e os itens da checklist; criadorId deve ser o membro da sessão (resolvido pelo login) e é recusado se diferir. Com chave já usada devolve a tarefa existente sem duplicar nem gerar nova mensagem (criacaoIdempotente). Recusa lista inativa (listaInativaNaoRecebeTarefa) e responsável que não seja membro ativo (responsavelDeveSerMembroAtivo). criadaEm é gravado pelo sistema; campos derivados são calculados na leitura.
   * Saída: tarefa completa para abrir no detalhe e resumo para inserir na lista sem nova consulta.
   */
  'tarefas.minhas_tarefas.salvarNovaTarefa': {
    kind: 'cmd';
    writes: 'Tarefa.create';
    input: { chaveCriacao: string; listaId: string; titulo: string; details: { descricao?: string }; prioridade: 'low' | 'medium' | 'high'; prazo: string; responsavelId: string; criadorId: string; checklist?: ItemChecklistEntrada[] };
    output: { tarefa: TarefaAberta; resumo: TarefaResumo };
    rules: ['criacaoIdempotente', 'listaInativaNaoRecebeTarefa', 'responsavelDeveSerMembroAtivo'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Salva a edição da tarefa aberta: campos, troca de responsável e ajustes da checklist.
   * Entrada: id e version: tarefa editada e versão para concorrência; listaId, titulo, descricao, prioridade, prazo, responsavelId: novos valores; checklist: itens finais (com id altera, sem id inclui, ausentes são removidos).
   * Processamento: Só edita tarefa visível ao membro (editarSomenteTarefaVisivel). Nunca altera status (edicaoNaoMudaSituacao, checklistNaoMudaSituacao). Se responsavelId mudou, exige que o membro seja o criador (reatribuicaoPorCriadorOuGestor) e que o novo seja membro ativo (responsavelDeveSerMembroAtivo), avisando o novo responsável. Recusa mover para lista inativa (listaInativaNaoRecebeTarefa). Grava tarefa e itens juntos e recusa version desatualizada.
   * Saída: tarefa atualizada para redesenhar detalhe e formulário e resumo para atualizar a linha da lista.
   */
  'tarefas.minhas_tarefas.salvarEdicaoTarefa': {
    kind: 'cmd';
    writes: 'Tarefa.update';
    input: { id: string; version: number; listaId: string; titulo: string; details: { descricao?: string }; prioridade: 'low' | 'medium' | 'high'; prazo: string; responsavelId: string; checklist?: ItemChecklistEntrada[] };
    output: { tarefa: TarefaAberta; resumo: TarefaResumo };
    rules: ['edicaoNaoMudaSituacao', 'editarSomenteTarefaVisivel', 'reatribuicaoPorCriadorOuGestor', 'responsavelDeveSerMembroAtivo', 'listaInativaNaoRecebeTarefa', 'checklistNaoMudaSituacao'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Inicia a tarefa, passando de a fazer para em andamento.
   * Entrada: id e version da tarefa aberta.
   * Processamento: Recusa se o membro da sessão não for o responsável (somenteResponsavelExecuta) ou se a tarefa estiver concluída/cancelada (tarefaEncerradaNaoTransiciona); aplica a transição iniciar e registra a mensagem na sala da tarefa.
   * Saída: tarefa e resumo atualizados para redesenhar detalhe, ações e lista.
   */
  'tarefas.minhas_tarefas.iniciarTarefa': {
    kind: 'cmd';
    writes: 'Tarefa.iniciar';
    input: { id: string; version: number };
    output: { tarefa: TarefaAberta; resumo: TarefaResumo };
    rules: ['somenteResponsavelExecuta', 'tarefaEncerradaNaoTransiciona'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Marca ou desmarca um item da checklist da tarefa aberta.
   * Entrada: id e version do item; feito: novo estado do item.
   * Processamento: Só altera itens de tarefa visível ao membro (editarSomenteTarefaVisivel); grava feito e marcadoEm (momento da marcação, vazio ao desmarcar) sem mudar a situação da tarefa (checklistNaoMudaSituacao). O progresso da checklist é derivado e recalculado na leitura.
   * Saída: tarefa com a checklist e o progresso atualizados e resumo para a linha da lista.
   */
  'tarefas.minhas_tarefas.marcarItemChecklist': {
    kind: 'cmd';
    writes: 'ItemChecklist.update';
    input: { id: string; version: number; feito: boolean };
    output: { tarefa: TarefaAberta; resumo: TarefaResumo };
    rules: ['checklistNaoMudaSituacao', 'editarSomenteTarefaVisivel'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Envia ou reenvia a tarefa para revisão do criador.
   * Entrada: id e version da tarefa aberta.
   * Processamento: Recusa se o membro não for o responsável (somenteResponsavelExecuta) ou se a tarefa estiver encerrada (tarefaEncerradaNaoTransiciona); passa de emAndamento para emRevisao, registra a mensagem e avisa o criador.
   * Saída: tarefa e resumo atualizados.
   */
  'tarefas.minhas_tarefas.enviarParaRevisao': {
    kind: 'cmd';
    writes: 'Tarefa.enviarParaRevisao';
    input: { id: string; version: number };
    output: { tarefa: TarefaAberta; resumo: TarefaResumo };
    rules: ['somenteResponsavelExecuta', 'tarefaEncerradaNaoTransiciona'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Aceita a entrega da tarefa em revisão, concluindo-a.
   * Entrada: id e version da tarefa aberta.
   * Processamento: Recusa se o membro não for o criador (somenteCriadorRevisa) ou se a tarefa já estiver encerrada (tarefaEncerradaNaoTransiciona); passa de emRevisao para concluida, grava concluidaEm e registra a mensagem.
   * Saída: tarefa e resumo atualizados, com o aceite no histórico.
   */
  'tarefas.minhas_tarefas.aceitarEntrega': {
    kind: 'cmd';
    writes: 'Tarefa.aceitar';
    input: { id: string; version: number };
    output: { tarefa: TarefaAberta; resumo: TarefaResumo };
    rules: ['somenteCriadorRevisa', 'tarefaEncerradaNaoTransiciona'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Devolve a tarefa em revisão para ajuste, com o motivo.
   * Entrada: id e version da tarefa; motivoDevolucao: explicação do que ajustar.
   * Processamento: Recusa se o membro não for o criador (somenteCriadorRevisa), se o motivo estiver vazio (devolucaoExigeMotivo) ou se a tarefa estiver encerrada (tarefaEncerradaNaoTransiciona); passa de emRevisao para emAndamento, grava motivo e devolvidaEm e avisa o responsável.
   * Saída: tarefa e resumo atualizados, com o motivo visível no detalhe e no histórico.
   */
  'tarefas.minhas_tarefas.devolverComMotivo': {
    kind: 'cmd';
    writes: 'Tarefa.devolver';
    input: { id: string; version: number; details: { motivoDevolucao: string } };
    output: { tarefa: TarefaAberta; resumo: TarefaResumo };
    rules: ['somenteCriadorRevisa', 'devolucaoExigeMotivo', 'tarefaEncerradaNaoTransiciona'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
  /**
   * Finalidade: Cancela uma tarefa que o membro criou.
   * Entrada: id e version da tarefa aberta.
   * Processamento: Recusa se o membro não for o criador (cancelamentoPorCriadorOuGestor) ou se a tarefa já estiver concluída ou cancelada (tarefaEncerradaNaoTransiciona); passa para cancelada, grava canceladaEm e registra a mensagem na sala.
   * Saída: tarefa e resumo atualizados com a situação cancelada.
   */
  'tarefas.minhas_tarefas.cancelarTarefa': {
    kind: 'cmd';
    writes: 'Tarefa.cancelar';
    input: { id: string; version: number };
    output: { tarefa: TarefaAberta; resumo: TarefaResumo };
    rules: ['cancelamentoPorCriadorOuGestor', 'tarefaEncerradaNaoTransiciona'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroConsultaListas', 'membroEscolheResponsavel']; scope: 'own' };
  };
}

/// <mls fileReference="_102047_/l2/tarefas/web/contracts/tarefas_equipe.defs.ts" enhancement="_blank"/>

/** Identificação do membro no cadastro mestre. */
export interface MembroIdentificacao {
  details: {
    identification: {
      name: string;
      readonly status?: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
    };
  };
}

export interface MembroDetalhes {
  identification: MembroIdentificacao;
}

/** Membro da equipe com id e nome, usado como responsável, criador ou opção de escolha. */
export interface MembroResumo {
  id: string;
  details: MembroDetalhes;
}

/** Lista com id e nome. */
export interface ListaResumo {
  id: string;
  nome: string;
}

export interface TarefaQuadroDetails {
  details: {
    readonly aberta: boolean;
    readonly venceHoje: boolean;
    readonly atrasada: boolean;
    readonly progressoChecklist: string;
  };
}

/** Linha do quadro de tarefas da equipe. */
export interface TarefaQuadroItem {
  id: string;
  titulo: string;
  status: 'aFazer' | 'emAndamento' | 'emRevisao' | 'concluida' | 'cancelada';
  prioridade: 'low' | 'medium' | 'high';
  prazo: string;
  listaId: string;
  responsavelId: string;
  details: TarefaQuadroDetails;
  lista: ListaResumo;
  responsavel: MembroResumo;
}

export interface ItemChecklistDetails {
  details: {
    descricao: string;
  };
}

/** Item da checklist da tarefa, na ordem. */
export interface ItemChecklistLinha {
  id: string;
  ordem: number;
  feito: boolean;
  details: ItemChecklistDetails;
}

export interface TarefaPaiResumo {
  id: string;
  titulo: string;
}

export interface TarefaDetalheDetails {
  details: {
    descricao?: string;
    motivoDevolucao?: string;
    devolvidaEm?: string;
    concluidaEm?: string;
    canceladaEm?: string;
    readonly aberta: boolean;
    readonly quantidadeSubtarefas: number;
    readonly progressoChecklist: string;
  };
}

/** Tarefa escolhida com lista, responsável, criador, tarefa pai, checklist e marcos do histórico. */
export interface TarefaDetalhe {
  id: string;
  version: number;
  titulo: string;
  status: 'aFazer' | 'emAndamento' | 'emRevisao' | 'concluida' | 'cancelada';
  prioridade: 'low' | 'medium' | 'high';
  prazo: string;
  listaId: string;
  responsavelId: string;
  criadorId: string;
  tarefaPaiId?: string;
  readonly criadaEm: string;
  details: TarefaDetalheDetails;
  lista: ListaResumo;
  responsavel: MembroResumo;
  criador: MembroResumo;
  tarefaPai?: TarefaPaiResumo;
  checklist: ItemChecklistLinha[];
}

export interface Tarefas_equipeContracts {
  /**
   * Finalidade: Carrega o quadro com todas as tarefas da equipe, já filtradas e paginadas, ao abrir a página e a cada mudança de filtro, busca ou página.
   * Entrada: listaId: lista; responsavelId: responsável; prioridade; prazoDe/prazoAte: período do prazo (inclusive); status: situações desejadas; busca: trecho do título; page/pageSize: paginação.
   * Processamento: Gestor vê todas as tarefas da equipe (escopo organização, editarSomenteTarefaVisivel). Aplica os filtros informados e a busca por título, ordena por prazo e prioridade. Junta o nome da lista e o nome do responsável (cadastro mestre) em lote. Calcula aberta, venceHoje, atrasada (com a data de hoje) e progressoChecklist (itens feitos / total) no servidor, sem gravar.
   * Saída: Página { items, page, pageSize, hasMore } de linhas prontas para o quadro, com indicação de vence hoje/atrasada e progresso da checklist.
   */
  'tarefas.tarefas_equipe.qryTarefasEquipe': {
    kind: 'qry';
    input: { listaId?: string; responsavelId?: string; prioridade?: 'low' | 'medium' | 'high'; prazo?: string; status?: Array<'aFazer' | 'emAndamento' | 'emRevisao' | 'concluida' | 'cancelada'>; titulo?: string; page: number; pageSize: number };
    output: { tarefas: { items: TarefaQuadroItem[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['editarSomenteTarefaVisivel'];
    access: { actors: ['gestor']; grants: ['gestorTarefasEquipe', 'gestorListas', 'gestorMembros']; scope: 'organization' };
  };
  /**
   * Finalidade: Carrega as opções do filtro por lista do quadro.
   * Entrada: Nenhuma.
   * Processamento: Lista todas as listas (ativas e inativas, pois tarefas antigas podem estar em listas inativas), ordenadas por nome.
   * Saída: Id e nome de cada lista para o seletor do filtro.
   */
  'tarefas.tarefas_equipe.qryListasFiltro': {
    kind: 'qry';
    input: {};
    output: { listas: ListaResumo[] };
    rules: [];
    access: { actors: ['gestor']; grants: ['gestorTarefasEquipe', 'gestorListas', 'gestorMembros']; scope: 'organization' };
  };
  /**
   * Finalidade: Busca membros da equipe pelo nome, para escolher o novo responsável na reatribuição ou o responsável no filtro do quadro.
   * Entrada: nome: trecho do nome digitado; somenteAtivos: true na escolha do novo responsável.
   * Processamento: Busca por nome no cadastro mestre entre os membros com papel tarefas.MembroEquipe. Com somenteAtivos, retorna só situação Active (responsavelDeveSerMembroAtivo). Limita a poucas dezenas de resultados, ordenados por nome.
   * Saída: Id, nome e situação dos membros encontrados.
   */
  'tarefas.tarefas_equipe.qryBuscarMembros': {
    kind: 'qry';
    input: { details: { identification: { name?: string } }; somenteAtivos?: boolean };
    output: { membros: MembroResumo[] };
    rules: ['responsavelDeveSerMembroAtivo'];
    access: { actors: ['gestor']; grants: ['gestorTarefasEquipe', 'gestorListas', 'gestorMembros']; scope: 'organization' };
  };
  /**
   * Finalidade: Abre a tarefa escolhida no quadro com tudo o que o detalhe, as ações e o histórico mostram, em uma chamada.
   * Entrada: tarefaId: id da tarefa selecionada no quadro.
   * Processamento: Lê a tarefa pelo id (gestor vê todas). Junta nome da lista, nomes do responsável e do criador, título da tarefa pai quando houver e os itens da checklist ordenados por ordem. Calcula aberta, quantidadeSubtarefas e progressoChecklist sem gravar. Os marcos do histórico (criadaEm, devolvidaEm com motivo, concluidaEm, canceladaEm, situação e responsável atual) vêm da própria tarefa.
   * Saída: Tarefa completa com version para as ações do gestor e os marcos para a linha do tempo.
   */
  'tarefas.tarefas_equipe.qryDetalheTarefa': {
    kind: 'qry';
    input: { tarefaId: string };
    output: { tarefa: TarefaDetalhe };
    rules: ['editarSomenteTarefaVisivel'];
    access: { actors: ['gestor']; grants: ['gestorTarefasEquipe', 'gestorListas', 'gestorMembros']; scope: 'organization' };
  };
  /**
   * Finalidade: Troca o responsável da tarefa escolhida pelo membro ativo selecionado e avisa o novo responsável.
   * Entrada: tarefaId: tarefa; version: versão lida, para concorrência otimista; responsavelId: novo responsável escolhido.
   * Processamento: Recusa se a versão mudou. Verifica que quem pede é o criador ou o gestor (reatribuicaoPorCriadorOuGestor) e que o novo responsável é membro ativo (responsavelDeveSerMembroAtivo). Grava só o responsável, sem alterar a situação (edicaoNaoMudaSituacao); quando a etapa é do responsável, ele passa a ser quem age agora e é avisado.
   * Saída: Tarefa atualizada no formato do detalhe e a linha do quadro atualizada, para redesenhar sem nova chamada.
   */
  'tarefas.tarefas_equipe.cmdReatribuirTarefa': {
    kind: 'cmd';
    writes: 'Tarefa.update';
    input: { id: string; version: number; responsavelId: string };
    output: { tarefa: TarefaDetalhe; itemQuadro: TarefaQuadroItem };
    rules: ['reatribuicaoPorCriadorOuGestor', 'responsavelDeveSerMembroAtivo', 'edicaoNaoMudaSituacao', 'editarSomenteTarefaVisivel'];
    access: { actors: ['gestor']; grants: ['gestorTarefasEquipe', 'gestorListas', 'gestorMembros']; scope: 'organization' };
  };
  /**
   * Finalidade: Cancela a tarefa escolhida após a confirmação do gestor.
   * Entrada: tarefaId: tarefa; version: versão lida, para concorrência otimista.
   * Processamento: Recusa se a versão mudou. Aplica a transição cancelar: só criador ou gestor e só a partir de a fazer, em andamento ou em revisão (cancelamentoPorCriadorOuGestor); tarefa concluída ou cancelada é recusada (tarefaEncerradaNaoTransciona). Registra canceladaEm e a mensagem na sala de discussão.
   * Saída: Tarefa cancelada no formato do detalhe (com canceladaEm para o histórico) e a linha do quadro atualizada.
   */
  'tarefas.tarefas_equipe.cmdCancelarTarefa': {
    kind: 'cmd';
    writes: 'Tarefa.cancelar';
    input: { id: string; version: number };
    output: { tarefa: TarefaDetalhe; itemQuadro: TarefaQuadroItem };
    rules: ['cancelamentoPorCriadorOuGestor', 'tarefaEncerradaNaoTransiciona'];
    access: { actors: ['gestor']; grants: ['gestorTarefasEquipe', 'gestorListas', 'gestorMembros']; scope: 'organization' };
  };
}

